         '  </div>',
         '  <nav class="al-sidebar__nav" aria-label="Principal">',
         '    <div class="al-sidebar__content">   <!-- só esta parte rola -->',
         '      <ul class="al-tabs al-tabs--square">   <!-- itens soltos: no topo, sem rótulo -->',
