REPO_URL = 'https://github.com/guilhermedworakowski/al-design-system'


def site_nav_group(rotulo, itens):
    gid = 'nav-g-' + sb_slug(rotulo)
    def li(pid, rot, sr=''):
        cur = ' aria-current="page"' if pid == 'fundacao' else ''
        extra = f'<span class="sr-only">{sr}</span>' if sr else ''
        return (f'<li><a class="al-tab" href="#/{pid}" data-page="{pid}"{cur}>'
                f'<span class="al-tab__label">{rot}{extra}</span></a></li>')
    lis = ''.join(li(*it) for it in itens)
    return (f'<div class="al-sidebar__group"><p class="al-sidebar__group-label" id="{gid}">{rotulo}</p>'
            f'<ul class="al-tabs al-tabs--square" aria-labelledby="{gid}">{lis}</ul></div>')


# Cada sigla é um link para a mesma página no outro idioma: EN na raiz, PT em
# pt/. O JS leva o hash junto, para cair no mesmo componente, e guarda a escolha.
LANG_HREF = {'en': {'en': 'index.html', 'pt': 'pt/index.html'},
             'pt': {'en': '../index.html', 'pt': 'index.html'}}[SITE_LANG]


def lang_opt(code, sigla, nome):
    cur = ' aria-current="true"' if code == SITE_LANG else ''
    hl = {'en': 'en', 'pt': 'pt-BR'}[code]
    return (f'<a class="lang__opt" href="{LANG_HREF[code]}" lang="{hl}" hreflang="{hl}" data-lang="{code}"'
            f' aria-label="{nome}"{cur}>{sigla}</a>')


LANG = (f'<div class="lang" role="group" aria-label="{tr("Idioma", "Language")}">'
        + lang_opt('en', 'EN', 'English')
        + '<span class="lang__sep" aria-hidden="true">/</span>'
        + lang_opt('pt', 'PT', 'Português') + '</div>')


def rail(nav):
    return (
    f'<a class="skip" href="#conteudo">{tr("Pular para o conteúdo", "Skip to content")}</a>\n'
    f'<aside class="al-sidebar" id="site-sidebar" aria-label="{tr("Barra lateral", "Sidebar")}">\n'
    '  <div class="al-sidebar__profile">\n'
    '    <span class="al-avatar al-avatar--md" aria-hidden="true"><span class="al-avatar__initials">AL</span></span>\n'
    '    <div class="al-sidebar__details">\n'
    '      <div class="al-sidebar__user">\n'
    '        <p class="al-sidebar__name">AL DS</p>\n'
    f'        <p class="al-sidebar__email">v{VERSION} - {META["license"]}</p>\n'
    '      </div>\n'
    f'      <a class="al-icon-btn al-icon-btn--ghost al-icon-btn--sm" href="{REPO_URL}" target="_blank"'
    f' rel="noopener" aria-label="{tr("Abrir o repositório no GitHub (abre em nova aba)", "Open the repository on GitHub (opens in a new tab)")}">'
    f'{al_icon("external-link")}</a>\n'
    '    </div>\n'
    '  </div>\n'
    f'  <nav class="al-sidebar__nav" aria-label="{tr("Navegação do design system", "Design system navigation")}">\n'
    '    <div class="al-sidebar__content">\n'
    + '\n'.join('      ' + site_nav_group(r, i) for r, i in nav) + '\n'
    '      <hr class="al-divider">\n'
    f'      {sw("themeswitch", tr("Tema escuro", "Dark theme"))}\n'
    '    </div>\n'
    '  </nav>\n'
    '</aside>')


RAIL = rail(SITE_NAV)

# O botão Menu é do produto (regra 24 da Sidebar): só existe abaixo de 1024px,
# quando a Sidebar vira painel modal pela esquerda (sidebar.js).
TOPBAR = (
    '<header class="topbar">'
    '<button type="button" class="al-icon-btn al-icon-btn--ghost al-icon-btn--md" aria-label="Menu"'
    ' aria-controls="site-sidebar" aria-expanded="false" data-al-sidebar-open="site-sidebar">'
    f'{al_icon("menu")}</button>'
    '<span class="topbar-name">AL Design System</span>' + LANG + '</header>')


FOOTER = f'''<footer class="site-footer"><div class="site-footer__inner">
  <p class="site-footer__name">AL Design System · <b>v{VERSION}</b></p>
  <p class="site-footer__credit">{tr('Design System open-source, da estratégia ao código', 'Open-source design system, from strategy to code')}</p>
  <p class="site-footer__license">{tr('Licença', 'License')} <b>{META['license']}</b></p>
</div></footer>'''

JS = r"""
(function () {
  // ── navegação: uma página por vez, endereçável pelo hash ──
  // Os itens são os Tab Square da .al-sidebar do site. O atual leva
  // aria-current="page"; página sem item (A prova)
  // fica sem nenhum marcado (regra 12 da Sidebar).
  var pages = [].slice.call(document.querySelectorAll('.page'));
  var links = [].slice.call(document.querySelectorAll('#site-sidebar a[data-page]'));
  // os cards das páginas-índice navegam pelo mesmo roteador que a Sidebar
  var cards = [].slice.call(document.querySelectorAll('a.card[data-page]'));
  // e o link "Visão geral" do breadcrumb de cada Hero
  var crumbs = [].slice.call(document.querySelectorAll('.hero a[data-page]'));

  function show(id) {
    var found = false;
    pages.forEach(function (p) {
      var on = p.id === 'pg-' + id;
      p.hidden = !on;
      if (on) found = true;
    });
    if (!found) return false;
    links.forEach(function (a) {
      if (a.getAttribute('data-page') === id) a.setAttribute('aria-current', 'page');
      else a.removeAttribute('aria-current');
    });
    return true;
  }

  function fromHash() {
    var id = (location.hash || '').replace(/^#\/?/, '');
    if (!id || !show(id)) show('fundacao');
    window.scrollTo(0, 0);
  }

  // O clique troca a página direto, sem depender do hashchange: em contexto
  // com o hash bloqueado (preview, sandbox, arquivo aberto local) o evento não
  // dispara, e a navegação ficaria morta. O hash continua sendo escrito para o
  // endereço permanecer copiável. Abaixo de 1024px o sidebar.js fecha o painel
  // no mesmo clique.
  links.concat(cards, crumbs).forEach(function (a) {
    a.addEventListener('click', function (e) {
      e.preventDefault();
      var id = a.getAttribute('data-page');
      if (!show(id)) return;
      window.scrollTo(0, 0);
      try { history.replaceState(null, '', '#/' + id); } catch (err) { /* sandbox */ }
    });
  });

  window.addEventListener('hashchange', fromHash);

  // ── switch de tema ──
  // Carimba data-theme na raiz, que é onde a Foundation resolve o tema. Só a
  // raiz serve: a substituição de custom property acontece no elemento onde o
  // alias é DECLARADO, e toda a camada semântica é declarada no :root.
  var root = document.documentElement;
  // idioma: cada sigla leva à mesma página no outro idioma, com o hash junto,
  // e guarda a escolha (a raiz em EN lê isso na carga, lá no <head>)
  document.querySelectorAll('.lang__opt').forEach(function (a) {
    a.addEventListener('click', function (e) {
      e.preventDefault();
      if (a.getAttribute('aria-current') === 'true') return;
      try { localStorage.setItem('al-lang', a.getAttribute('data-lang')); } catch (err) { /* sem storage */ }
      location.href = a.getAttribute('href') + location.hash;
    });
  });
  var sw = document.getElementById('themeswitch');

  function applyTheme(dark, remember) {
    root.setAttribute('data-theme', dark ? 'dark' : 'light');
    sw.checked = dark;
    if (remember) {
      try { localStorage.setItem('al-theme', dark ? 'dark' : 'light'); } catch (e) { /* sem storage */ }
    }
  }

  // Estado inicial. A Foundation tem TRÊS estados, não dois: sem carimbo, quem
  // decide é o sistema. Carimbar na carga mataria o terceiro estado, então
  // enquanto o leitor não tocar no switch a página continua seguindo o sistema
  // e o switch apenas reflete o que está na tela.
  var saved = null;
  try { saved = localStorage.getItem('al-theme'); } catch (e) { /* sem storage */ }
  var mq = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;
  var stamped = root.getAttribute('data-theme');

  if (saved) {
    applyTheme(saved === 'dark', false);          // escolha anterior: carimba
  } else if (stamped) {
    sw.checked = stamped === 'dark';
  } else {
    sw.checked = !!(mq && mq.matches);
    if (mq && mq.addEventListener) {
      mq.addEventListener('change', function (e) {
        if (!root.getAttribute('data-theme')) {
          sw.checked = e.matches;
        }
      });
    }
  }

  // O input nativo ja trocou o `checked` quando o evento chega: so carimbar.
  sw.addEventListener('change', function () {
    applyTheme(sw.checked, true);
  });

  // Se o ambiente reescrever data-theme por fora (o visualizador tem o próprio
  // controle de tema), o switch acompanha em vez de ficar mentindo.
  if (window.MutationObserver) {
    new MutationObserver(function () {
      var dark = root.getAttribute('data-theme') === 'dark';
      if (sw.checked !== dark) sw.checked = dark;
    }).observe(root, { attributes: true, attributeFilter: ['data-theme'] });
  }

  // As abas das páginas são ligadas pelo tab.js do AL (setas, Home, End e painel).

  // ── playground do Button ──
  var demo = document.getElementById('demo');
  var stage = document.getElementById('stage');
  var code = document.getElementById('code');
  var lead = demo.querySelector('.al-btn__icon--leading');
  var trail = demo.querySelector('.al-btn__icon--trailing');
  var label = demo.querySelector('.al-btn__label');
  var input = document.getElementById('btn-label');

  function pick(name) {
    var el = document.querySelector('input[name="' + name + '"]:checked, select[name="' + name + '"]');
    return el ? el.value : null;
  }

  // os controles são o Select, o Radio e o Input do AL
  function val(name) {
    var r = document.querySelector('input[name="btn-' + name + '"]:checked');
    return r ? r.value : document.getElementById('btn-' + name).value;
  }
  function setVal(name, v) {
    var r = document.querySelector('input[name="btn-' + name + '"][value="' + v + '"]');
    if (r) r.checked = true;
    else document.getElementById('btn-' + name).value = v;
  }

  function render() {
    var variant = val('variant'), size = val('size');
    var state = val('state'), icon = val('icon'), theme = val('theme');

    demo.className = 'al-btn al-btn--' + variant + ' al-btn--' + size
      + (state === 'hover' || state === 'active' || state === 'focus' ? ' is-' + state : '');

    demo.removeAttribute('aria-disabled');
    demo.removeAttribute('aria-busy');
    if (state === 'disabled') demo.setAttribute('aria-disabled', 'true');
    if (state === 'busy') {
      demo.setAttribute('aria-busy', 'true');
      demo.setAttribute('aria-disabled', 'true');
    }

    lead.hidden = !(icon === 'leading');
    trail.hidden = !(icon === 'trailing');
    label.textContent = input.value || 'Button';

    if (theme === 'auto') stage.removeAttribute('data-theme');
    else stage.setAttribute('data-theme', theme);

    // marcação gerada, na ordem em que o contrato pede
    var cls = 'al-btn al-btn--' + variant + ' al-btn--' + size;
    var attrs = '';
    if (state === 'disabled') attrs = ' aria-disabled="true"';
    if (state === 'busy') attrs = ' aria-busy="true" aria-disabled="true"';
    var lines = ['&lt;button type="button" class="' + cls + '"' + attrs + '&gt;'];
    if (state === 'busy') lines.push('  &lt;span class="al-btn__spinner" aria-hidden="true"&gt;&lt;/span&gt;');
    if (icon === 'leading' && state !== 'busy') {
      lines.push('  &lt;span class="al-btn__icon al-btn__icon--leading"&gt;');
      lines.push('    &lt;svg class="al-icon" aria-hidden="true" focusable="false"&gt;&lt;!-- LEADING --&gt;&lt;/svg&gt;');
      lines.push('  &lt;/span&gt;');
    }
    lines.push('  &lt;span class="al-btn__label"&gt;' +
      (input.value || 'Button').replace(/&/g, '&amp;').replace(/</g, '&lt;') + '&lt;/span&gt;');
    if (icon === 'trailing') {
      lines.push('  &lt;span class="al-btn__icon al-btn__icon--trailing"&gt;');
      lines.push('    &lt;svg class="al-icon" aria-hidden="true" focusable="false"&gt;&lt;!-- TRAILING --&gt;&lt;/svg&gt;');
      lines.push('  &lt;/span&gt;');
    }
    lines.push('&lt;/button&gt;');
    code.innerHTML = lines.join('\n');
  }

  document.querySelectorAll('#btn-controls select, #btn-controls input').forEach(function (el) {
    el.addEventListener('change', render);
    el.addEventListener('input', render);
  });

  // "Abrir no playground" dos exemplos: configura os controles e abre a aba
  document.querySelectorAll('#pg-button [data-pg-preset]').forEach(function (b) {
    b.addEventListener('click', function () {
      var preset = JSON.parse(b.getAttribute('data-pg-preset'));
      ['variant', 'size', 'state', 'icon'].forEach(function (k) {
        if (preset[k]) setVal(k, preset[k]);
      });
      if (preset.label) input.value = preset.label;
      render();
      var tab = document.getElementById('t-button-playground');
      tab.click();
      tab.focus();
      document.getElementById('p-button-playground').scrollIntoView({ block: 'start' });
    });
  });

  // copiar marcação
  document.getElementById('copy').addEventListener('click', function () {
    var btn = this;
    var text = code.textContent;
    var done = function () {
      btn.textContent = AL_T.copied;
      setTimeout(function () { btn.textContent = AL_T.copy; }, 1600);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done, function () { btn.textContent = AL_T.failed; });
    } else {
      var ta = document.createElement('textarea');
      ta.value = text; document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); done(); } catch (e) { btn.textContent = AL_T.failed; }
      document.body.removeChild(ta);
    }
  });

  render();
  fromHash();
})();
"""

